const wantUSSPList = `-- name: WantUSSPList :one
UPDATE certificate_list_state SET wanted = wanted + 1 WHERE id RETURNING wanted
`

// A transition changed the USSP list: one more version is wanted.
func (q *Queries) WantUSSPList(ctx context.Context) (int64, error) {
	row := q.db.QueryRow(ctx, wantUSSPList)
	var wanted int64
	err := row.Scan(&wanted)
	return wanted, err
}
